const d = msg.payload;
if (!d || typeof d !== 'object' || d.suhu === undefined) return null;
d.received = new Date().toISOString();
let th = flow.get('threshold');
if (th === undefined) th = 30;
d.threshold = th;
d.over = d.suhu > th;
flow.set('lastSensor', d);
const insert = { params: { $suhu: d.suhu, $kelembaban: d.kelembaban, $ts: d.timestamp, $received: d.received } };
const ws = { payload: { type: 'sensor', data: d } };
let alert = null;
const was = flow.get('alerting') || false;
if (d.over && !was) {
  alert = { topic: 'iot/notifikasi', payload: { type: 'alert',
    message: 'Suhu ' + d.suhu + '°C melewati batas ' + th + '°C',
    suhu: d.suhu, batas: th, waktu: d.received } };
}
flow.set('alerting', d.over);
return [insert, ws, alert];

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== KEY) {
  msg.statusCode = 401;
  msg.headers = {'Access-Control-Allow-Origin':'*'};
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada (header X-API-Key)'};
  return [null, msg];
}
return [msg, null];

const d = flow.get('lastSensor') || {suhu:null, kelembaban:null, timestamp:null};
const th = flow.get('threshold');
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin':'*'};
msg.payload = {status:'success', data:d, threshold:(th === undefined ? 30 : th), server_time:new Date().toISOString()};
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== KEY) {
  msg.statusCode = 401;
  msg.headers = {'Access-Control-Allow-Origin':'*'};
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada (header X-API-Key)'};
  return [null, msg];
}
return [msg, null];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin':'*'};
msg.payload = {status:'success', count:rows.length, data:rows};
return msg;

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== KEY) {
  msg.statusCode = 401;
  msg.headers = {'Access-Control-Allow-Origin':'*'};
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada (header X-API-Key)'};
  return [null, msg];
}
return [msg, null];

const body = msg.payload || {};
msg.headers = {'Access-Control-Allow-Origin':'*'};
if (!body.device || !body.action) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'device dan action wajib diisi'};
  return [msg, null];
}
msg.statusCode = 200;
msg.payload = {status:'success', message:'Perintah terkirim', sent:body};
return [msg, {topic:'iot/kontrol', payload:body}];

const KEY = env.get('API_KEY') || 'iot-kampus-2026';
if (msg.req.headers['x-api-key'] !== KEY) {
  msg.statusCode = 401;
  msg.headers = {'Access-Control-Allow-Origin':'*'};
  msg.payload = {status:'error', message:'API key tidak valid atau tidak ada (header X-API-Key)'};
  return [null, msg];
}
return [msg, null];

const b = msg.payload ? msg.payload.batas : undefined;
msg.headers = {'Access-Control-Allow-Origin':'*'};
if (typeof b !== 'number' || !isFinite(b) || b < -40 || b > 125) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'batas harus angka antara -40 dan 125'};
  return msg;
}
flow.set('threshold', b);
flow.set('alerting', false);
msg.statusCode = 200;
msg.payload = {status:'success', message:'Batas suhu diperbarui', batas:b};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
